  for _ in range(random.randrange(8)):
   l=random.randrange(n); r=random.randrange(l,n); x=random.randrange(l,r+1); cons.append((l,r,x))
  brute=0
  for p in itertools.permutations(range(n)):
   if all(max(range(l,r+1),key=lambda i:p[i])!=x for l,r,x in cons):brute+=1
  # recursive cartesian DP memo directly
  from functools import lru_cache
  @lru_cache(None)
  def f(l,r):
