from itertools import product

def fast(s):
 p=[i for i,c in enumerate(s) if c=='1']
 q=[x-i for i,x in enumerate(p)]
 m=q[len(q)//2]
 return sum(abs(x-m) for x in q)
def brute(s):
 n=len(s); k=s.count('1')
 best=10**9
 for st in range(n-k+1):
  t='0'*st+'1'*k+'0'*(n-k-st)
  # Hamming/2 is number ones that must move? adjacent swaps distance for binary strings
  a=[i for i,c in enumerate(s) if c=='1']; b=[i for i,c in enumerate(t) if c=='1']
  best=min(best,sum(abs(x-y) for x,y in zip(a,b)))
 return best
for n in range(2,10):
 for bits in product('01', repeat=n):
  s=''.join(bits)
  if '1' in s and fast(s)!=brute(s): raise Exception((s,fast(s),brute(s)))
