import sys

def solve():
 data=list(map(int,sys.stdin.buffer.read().split())); n=data[0]; a=data[1:]
 fac=[]
 for x in a:
  d={}; q=x; p=2
  while p*p<=q:
   while q%p==0:d[p]=d.get(p,0)+1;q//=p
   p+=1
  if q>1:d[q]=d.get(q,0)+1
  fac.append(d)
 primes=set().union(*(x.keys() for x in fac)) if fac else set(); ans=1
 for p in primes:
  ex=[d.get(p,0) for d in fac]; E=sum(ex)
  pw=[1]*(E+1)
  for i in range(1,E+1):pw[i]=pw[i-1]*p%MOD
  no=[0]*(E+1); yes=[0]*(E+1)
  for k in range(E+1):(yes if k==0 else no).__setitem__(k,pw[k])
  for e in ex:
   if not e:
    for j in range(E+1):no[j]=no[j]*pw[j]%MOD;yes[j]=yes[j]*pw[j]%MOD
    continue
   nn=[0]*(E+1); yy=[0]*(E+1)
   for j in range(E+1):
    for z in (j-e,j+e):
     if 0<=z<=E:
      w=pw[z]
      if z==0: yy[z]=(yy[z]+(no[j]+yes[j])*w)%MOD
      else:
       nn[z]=(nn[z]+no[j]*w)%MOD
       yy[z]=(yy[z]+yes[j]*w)%MOD
   no,yes=nn,yy
  ans=ans*sum(yes)%MOD
 print(ans)
solve()

