import sys

MOD = 998244353

def main():
    data = list(map(int, sys.stdin.buffer.read().split()))
    if not data:
        return
    n = data[0]
    a = data[1:]
    V = max(a)

    phi = list(range(V + 1))
    if V >= 1:
        phi[1] = 1
    for p in range(2, V + 1):
        if phi[p] == p:
            for k in range(p, V + 1, p):
                phi[k] -= phi[k] // p

    divs = [[] for _ in range(V + 1)]
    for d in range(1, V + 1):
        for x in range(d, V + 1, d):
            divs[x].append(d)

    cnt = [0] * (V + 1)
    ans = 0
    wt = 1
    out = []
    for x in a:
        s = 0
        for d in divs[x]:
            s += phi[d] * cnt[d]
        s %= MOD
        ans = (2 * ans + s) % MOD
        for d in divs[x]:
            v = cnt[d] + wt
            if v >= MOD:
                v -= MOD
            cnt[d] = v
        wt = wt * 2 % MOD
        out.append(str(ans))
    sys.stdout.write('\n'.join(out))

if __name__ == '__main__':
    main()

