import sys

def main():
    data = list(map(int, sys.stdin.buffer.read().split()))
    n = data[0]
    a = data[1:1 + n]
    mx = max(a, default=1)

    spf = list(range(mx + 1))
    for p in range(2, int(mx ** 0.5) + 1):
        if spf[p] == p:
            for x in range(p * p, mx + 1, p):
                if spf[x] == x:
                    spf[x] = p

    nim_sum = 0
    for x in a:
        factors = 0
        while x > 1:
            factors += 1
            x //= spf[x]
        nim_sum ^= factors

    print('Anna' if nim_sum else 'Bruno')

if __name__ == '__main__':
    main()

