def fast(n, ps):
 b=[[] for _ in range(n+1)]
 for i,(x,y) in enumerate(ps):
  a,c=sorted((x,y));b[c].append((a,i))
 h=[]; g=[0]*len(ps);t=0
 for r in range(1,n+1):
  for a,i in b[r]:heapq.heappush(h,(-a,i))
  if not h:t+=r;continue
  z,i=heapq.heappop(h);top=-z;sec=-h[0][0] if h else 0
  g[i]+=top-sec;heapq.heappush(h,(z,i));t+=r-top
 return t+max(g)
