  for l in range(1,n+1):
   for r in range(l,n+1):
    if all(not (l<=min(x,y) and r>=max(x,y)) for j,(x,y) in enumerate(ps) if j!=rem):cur+=1
  ans=max(ans,cur)
 return ans
