class Solution:
    def countKReducibleNumbers(self, s: str, k: int) -> int:
        MOD = 10**9 + 7
        m = len(s)

        # depth[x] is the number of popcount operations needed to reach 1.
        depth = [0] * (m + 1)
        for x in range(2, m + 1):
            depth[x] = 1 + depth[x.bit_count()]

        # Binomial coefficients modulo MOD.
        comb = [[0] * (m + 1) for _ in range(m + 1)]
        comb[0][0] = 1
        for i in range(1, m + 1):
            comb[i][0] = comb[i][i] = 1
            for j in range(1, i):
                comb[i][j] = (comb[i - 1][j - 1] + comb[i - 1][j]) % MOD

        ans = 0
        for ones in range(1, m + 1):
            if depth[ones] > k - 1:
                continue
            used = 0
            ways = 0
            for i, ch in enumerate(s):
                if ch == '1':
                    rem = m - i - 1
                    need = ones - used
                    if 0 <= need <= rem:
                        ways += comb[rem][need]
                    used += 1
                    if used > ones:
                        break
            ans = (ans + ways) % MOD
        return ans

