        trains.append((a - 1, b - 1, s, t))

    delays = [0] * m
    delays[0] = x1
    events = []
    for i, (_, _, s, t) in enumerate(trains):
        # Arrival events precede departure queries at the same time.
        events.append((t, 0, i))
        events.append((s, 1, i))

    best_arrival = [None] * n
    for time, kind, i in sorted(events):
        a, b, s, t = trains[i]
        if kind == 0:
