import sys
from bisect import bisect_left, bisect_right

def main():
    data = sys.stdin.buffer.read().split()
    if not data:
        return
    N, Q = map(int, data[:2])
    s = data[2].decode()
    ones, twos, slashes = [], [], []
    for i, c in enumerate(s):
        if c == '1':
            ones.append(i)
        elif c == '2':
            twos.append(i)
        else:
            slashes.append(i)

    out = []
    at = 3
    for _ in range(Q):
        L, R = map(int, data[at:at + 2])
        at += 2
        l, r = L - 1, R - 1
        a = bisect_left(ones, l)
        b = bisect_right(ones, r)
        c = bisect_left(twos, l)
        d = bisect_right(twos, r)
        hi = min(b - a, d - c)

        def feasible(k):
            if k == 0:
                x = bisect_left(slashes, l)
                return x < len(slashes) and slashes[x] <= r
            p = ones[a + k - 1]
            t = twos[d - k]
            x = bisect_left(slashes, p + 1)
            return x < len(slashes) and slashes[x] < t and slashes[x] <= r

        lo = 0
        while lo < hi:
            mid = (lo + hi + 1) // 2
            if feasible(mid):
                lo = mid
            else:
                hi = mid - 1
        if lo == 0 and not feasible(0):
            out.append('0')
        else:
            out.append(str(2 * lo + 1))

    sys.stdout.write('\n'.join(out))

if __name__ == '__main__':
    main()

