from typing import List
class Solution:
    def lenOfVDiagonal(self, grid: List[List[int]]) -> int:
        n, m = len(grid), len(grid[0])
        dirs = [(-1,-1), (-1,1), (1,1), (1,-1)]
        size = n * m
        straight = [[0] * size for _ in range(4)]
        turned = [[0] * size for _ in range(4)]
        for d, (dr, dc) in enumerate(dirs):
            rows = range(n - 1, -1, -1) if dr == 1 else range(n)
            for r in rows:
                base = r * m
                nr = r + dr
                for c in range(m):
                    v = grid[r][c]
                    if v not in (0, 2):
                        continue
                    nc = c + dc
                    idx = base + c
                    if 0 <= nr < n and 0 <= nc < m and grid[nr][nc] == 2 - v:
                        straight[d][idx] = 1 + straight[d][nr * m + nc]
                    else:
                        straight[d][idx] = 1
        for d, (dr, dc) in enumerate(dirs):
            rows = range(n - 1, -1, -1) if dr == 1 else range(n)
            td = (d + 1) % 4
            tdr, tdc = dirs[td]
            for r in rows:
                base = r * m
                nr, tr = r + dr, r + tdr
                for c in range(m):
                    v = grid[r][c]
                    if v not in (0, 2):
                        continue
                    nc, tc = c + dc, c + tdc
                    same = 0
                    if 0 <= nr < n and 0 <= nc < m and grid[nr][nc] == 2 - v:
                        same = turned[d][nr * m + nc]
                    bend = 0
                    if 0 <= tr < n and 0 <= tc < m and grid[tr][tc] == 2 - v:
                        bend = straight[td][tr * m + tc]
                    turned[d][base + c] = 1 + max(same, bend)
        ans = 0
        for r in range(n):
            for c in range(m):
                if grid[r][c] == 1:
                    ans = max(ans, 1)
                    for d, (dr, dc) in enumerate(dirs):
                        nr, nc = r + dr, c + dc
                        if 0 <= nr < n and 0 <= nc < m and grid[nr][nc] == 2:
                            ans = max(ans, 1 + turned[d][nr * m + nc])
        return ans

