from typing import List
from functools import lru_cache
class Solution:
    def lenOfVDiagonal(self, grid: List[List[int]]) -> int:
        n, m = len(grid), len(grid[0])
        # clockwise: NW, NE, SE, SW
        dirs = [(-1,-1), (-1,1), (1,1), (1,-1)]
        @lru_cache(None)
        def go(r, c, d, need, can_turn):
            if not (0 <= r < n and 0 <= c < m) or grid[r][c] != need:
                return 0
            nr, nc = r + dirs[d][0], c + dirs[d][1]
            nxt = 0 if need == 1 else 2 - need
            best = go(nr, nc, d, nxt, can_turn)
            if can_turn:
                td = (d + 1) % 4
                tr, tc = r + dirs[td][0], c + dirs[td][1]
                best = max(best, go(tr, tc, td, nxt, False))
            return 1 + best
        ans = 0
        for r in range(n):
            for c in range(m):
                if grid[r][c] == 1:
                    ans = max(ans, 1)
                    for d in range(4):
                        nr, nc = r + dirs[d][0], c + dirs[d][1]
                        ans = max(ans, 1 + go(nr, nc, d, 2, True))
        return ans

from typing import List
class Solution:
    def lenOfVDiagonal(self, grid: List[List[int]]) -> int:
        n, m = len(grid), len(grid[0])
        dirs = [(-1,-1), (-1,1), (1,1), (1,-1)]  # clockwise
        size = n * m
        straight = [[0] * size for _ in range(4)]
        turned = [[0] * size for _ in range(4)]
        # A step changes row, so reverse row order computes all dependencies first.
        for d, (dr, dc) in enumerate(dirs):
            rows = range(n - 1, -1, -1) if dr == 1 else range(n)
            td = (d + 1) % 4
            for r in rows:
                base = r * m
                nr = r + dr
                for c in range(m):
                    v = grid[r][c]
                    if v == 1:
                        continue
                    idx = base + c
                    nc = c + dc
                    if 0 <= nr < n and 0 <= nc < m and grid[nr][nc] == 2 - v:
                        ni = nr * m + nc
                        straight[d][idx] = 1 + straight[d][ni]
                        turned[d][idx] = 1 + max(turned[d][ni], straight[td][ni])
                    else:
                        straight[d][idx] = 1
                        turned[d][idx] = 1
        ans = 0
        for r in range(n):
            for c in range(m):
                if grid[r][c] != 1:
