from typing import List

class Solution:
    def permute(self, n: int, k: int) -> List[int]:
        odds = list(range(1, n + 1, 2))
        evens = list(range(2, n + 1, 2))
        fact = [1] * (n + 1)
        for i in range(1, n + 1):
            fact[i] = fact[i - 1] * i

        def ways(o, e, first):
            length = o + e
            if length == 0:
                return 1
            first_count = (length + 1) // 2
            second_count = length // 2
            if first == 1:
                if o != first_count or e != second_count:
                    return 0
            else:
                if e != first_count or o != second_count:
                    return 0
            return fact[o] * fact[e]

        result = []
        o, e = len(odds), len(evens)
        required = None
        while o + e:
            found = False
            for x in sorted(odds + evens):
                parity = x % 2
                if required is not None and parity != required:
                    continue
                if parity:
                    odds.remove(x)
                    o -= 1
                else:
                    evens.remove(x)
                    e -= 1
                count = 1 if o + e == 0 else ways(o, e, 1 - parity)
                if k > count:
                    k -= count
                    if parity:
                        odds.append(x)
                        o += 1
                    else:
                        evens.append(x)
                        e += 1
                    continue
                result.append(x)
                required = 1 - parity
                found = True
                break
            if not found:
                return []
        return result

