class Solution:
    def largestPalindrome(self, n: int, k: int) -> str:
        m = (n + 1) // 2
        coeff = []
        for i in range(m):
            j = n - 1 - i
            c = pow(10, i, k)
            if i != j:
                c = (c + pow(10, j, k)) % k
            coeff.append(c)

        # suffix[i] is a bitmask of remainders attainable using positions i..m-1.
        suffix = [0] * (m + 1)
        suffix[m] = 1
        for i in range(m - 1, -1, -1):
            mask = 0
            for r in range(k):
                if suffix[i + 1] >> r & 1:
                    for d in range(10):
                        mask |= 1 << ((r + d * coeff[i]) % k)
            suffix[i] = mask

        digits = []
        prefix_remainder = 0
        for i, c in enumerate(coeff):
            low = 1 if i == 0 else 0
            for d in range(9, low - 1, -1):
                needed = (-prefix_remainder - d * c) % k
                if suffix[i + 1] >> needed & 1:
                    digits.append(str(d))
                    prefix_remainder = (prefix_remainder + d * c) % k
                    break

        left = ''.join(digits)
        return left + left[:n // 2][::-1]

