class Solution:
    def countNonDecreasingSubarrays(self, nums: List[int], k: int) -> int:
        n = len(nums)
        nxt = [n] * (n + 1)
        st = []
        for i in range(n - 1, -1, -1):
            while st and nums[st[-1]] <= nums[i]:
                st.pop()
            if st:
                nxt[i] = st[-1]
            st.append(i)
        levels = n.bit_length()
        jumps = [array('i', nxt)]
        sums = [array('q', [nums[i] * (nxt[i] - i) for i in range(n)] + [0])]
        for _ in range(1, levels):
            prev = jumps[-1]
            oldsum = sums[-1]
            jumps.append(array('i', (prev[prev[i]] for i in range(n + 1))))
            sums.append(array('q', (oldsum[i] + oldsum[prev[i]] for i in range(n + 1))))
        pref = [0]
        for x in nums:
            pref.append(pref[-1] + x)
        def cost(l, R):
            cur = l
            total = 0
            for lev in range(levels - 1, -1, -1):
                if cur < R:
                    landing = jumps[lev][cur]
                    if landing <= R:
                        total += sums[lev][cur]
                        cur = landing
            if cur < R:
                total += (R - cur) * nums[cur]
            return total - (pref[R] - pref[l])
        ans = 0
        r = 0
        for l in range(n):
            if r < l:
                r = l
            while r < n and cost(l, r + 1) <= k:
                r += 1
            ans += r - l
        return ans

