class Solution:
    def makeStringGood(self, s: str) -> int:
        c = [0] * 26
        for ch in s:
            c[ord(ch) - 97] += 1
        n = len(s)
        ans = n
        for x in range(1, max(c) + 1):
            # dp[p] is the minimum cost after processing the previous
            # letters, forwarding p characters to the current letter.
            dp = [10**9] * (n + 1)
            dp[0] = 0
            for i in range(25):
                # Distance transform: min_p(dp[p] + abs(p-z)).
                left = [0] * (n + 1)
                best = 10**9
                for z in range(n + 1):
                    best = min(best, dp[z] - z)
                    left[z] = best + z
                right = [0] * (n + 1)
                best = 10**9
                for z in range(n, -1, -1):
                    best = min(best, dp[z] + z)
                    right[z] = best - z

                nd = [10**9] * (n + 1)
                for y in range(n + 1):
                    val = 10**9
                    for d in (0, x):
                        z = y + d - c[i]
                        if 0 <= z <= n:
                            val = min(val, left[z], right[z])
                    if val < 10**9:
                        nd[y] = val + y
                dp = nd

            # The final letter cannot forward characters any further.
            for d in (0, x):
                z = d - c[25]
                if 0 <= z <= n:
                    ans = min(ans, dp[z])
        return ans

