from bisect import bisect_right, bisect_left

class Solution:
    def shortestMatchingSubstring(self, s: str, p: str) -> int:
        i = p.index('*')
        j = p.index('*', i + 1)
        a, b, c = p[:i], p[i+1:j], p[j+1:]
        n = len(s)

        def occurrences(t):
            if not t:
                return list(range(n + 1))
            # KMP prefix function
            pi = [0] * len(t)
            for x in range(1, len(t)):
                k = pi[x - 1]
                while k and t[x] != t[k]:
                    k = pi[k - 1]
                if t[x] == t[k]:
                    k += 1
                pi[x] = k
            out = []
            k = 0
            for x, ch in enumerate(s):
                while k and ch != t[k]:
                    k = pi[k - 1]
                if ch == t[k]:
                    k += 1
                if k == len(t):
                    out.append(x - len(t) + 1)
                    k = pi[k - 1]
            return out

        ao = occurrences(a)
        bo = occurrences(b)
        co = occurrences(c)
        ans = n + 1
        for x in bo:
            if a:
                q = bisect_right(ao, x - len(a)) - 1
                if q < 0:
                    continue
                start = ao[q]
            else:
                start = x
            y = x + len(b)
            if c:
                q = bisect_left(co, y)
                if q == len(co):
                    continue
                end = co[q] + len(c)
            else:
                end = y
            ans = min(ans, end - start)
        return -1 if ans == n + 1 else ans

