from typing import List

class Solution:
    def findAnswer(self, parent: List[int], s: str) -> List[bool]:
        n = len(parent)
        children = [[] for _ in range(n)]
        for v in range(1, n):
            children[parent[v]].append(v)

        # Iterative postorder traversal, preserving increasing child order.
        post = []
        stack = [(0, False)]
        while stack:
            u, done = stack.pop()
            if done:
                post.append(u)
            else:
                stack.append((u, True))
                for v in reversed(children[u]):
                    stack.append((v, False))

        pos = [0] * n
        size = [1] * n
        chars = []
        for i, u in enumerate(post):
            pos[u] = i
            chars.append(s[u])
            if parent[u] != -1:
                size[parent[u]] += size[u]
        t = ''.join(chars)

        # Manacher radii for odd- and even-length palindromes.
        d1 = [0] * n
        left = 0
        right = -1
        for i in range(n):
            k = 1 if i > right else min(d1[left + right - i], right - i + 1)
            while i - k >= 0 and i + k < n and t[i - k] == t[i + k]:
                k += 1
            d1[i] = k
            if i + k - 1 > right:
                left, right = i - k + 1, i + k - 1

        d2 = [0] * n
        left = 0
        right = -1
        for i in range(n):
            k = 0 if i > right else min(d2[left + right - i + 1], right - i + 1)
            while i - k - 1 >= 0 and i + k < n and t[i - k - 1] == t[i + k]:
                k += 1
            d2[i] = k
            if i + k - 1 > right:
                left, right = i - k, i + k - 1

        answer = [False] * n
        for u in range(n):
            r = pos[u]
            l = r - size[u] + 1
            length = size[u]
            if length % 2:
                answer[u] = d1[(l + r) // 2] >= length // 2 + 1
            else:
                answer[u] = d2[(l + r + 1) // 2] >= length // 2
        return answer

