import math, bisect

def fast(N):
    limit=math.isqrt(N)
    s=bytearray(b'\1')*(limit+1)
    if limit>=0: s[:min(2,limit+1)]=b'\0'*min(2,limit+1)
    for p in range(2,math.isqrt(limit)+1):
        if s[p]:
            st=p*p;s[st:limit+1:p]=b'\0'*(((limit-st)//p)+1)
    ps=[i for i in range(2,limit+1) if s[i]]; X=math.isqrt(N); a=0
    for i,p in enumerate(ps):
        if p*p>X: break
        a+=max(0,bisect.bisect_right(ps,X//p)-i-1)
    for p in ps:
        if p**8<=N:a+=1
        else:break
    return a

def brute(N):
    ans=0
    for x in range(1,N+1):
        d=0
        for i in range(1,math.isqrt(x)+1):
            if x%i==0:d+=1+(i*i!=x)
        ans+=d==9
    return ans
for n in range(1,1000):
    assert fast(n)==brute(n),(n,fast(n),brute(n))
