from typing import List

class Solution:
    def minZeroArray(self, nums: List[int], queries: List[List[int]]) -> int:
        n = len(nums)
        if all(x == 0 for x in nums):
            return 0
        reachable = [1] * n
        targets = nums
        for k, (l, r, val) in enumerate(queries, 1):
            for i in range(l, r + 1):
                if targets[i] > 0:
                    reachable[i] |= reachable[i] << val
                    reachable[i] &= (1 << (targets[i] + 1)) - 1
            if all((reachable[i] >> targets[i]) & 1 for i in range(n)):
                return k
        return -1

