import heapq

class Solution:
    def minOperations(self, n: int, m: int) -> int:
        limit = 10 ** len(str(n))
        prime = [True] * limit
        prime[0] = False
        if limit > 1:
            prime[1] = False
        for p in range(2, int(limit ** 0.5) + 1):
            if prime[p]:
                for x in range(p * p, limit, p):
                    prime[x] = False

        if prime[n] or prime[m]:
            return -1

        dist = {n: n}
        pq = [(n, n)]
        while pq:
            cost, x = heapq.heappop(pq)
            if dist.get(x) != cost:
                continue
            if x == m:
                return cost

            s = str(x)
            for i, ch in enumerate(s):
                digit = ord(ch) - ord('0')
                place = 10 ** (len(s) - 1 - i)

                if digit < 9:
                    y = x + place
                    if not prime[y] and cost + y < dist.get(y, float('inf')):
                        dist[y] = cost + y
                        heapq.heappush(pq, (cost + y, y))
                if digit > 0:
                    y = x - place
                    if not prime[y] and cost + y < dist.get(y, float('inf')):
                        dist[y] = cost + y
                        heapq.heappush(pq, (cost + y, y))

        return -1

