from typing import List

class Solution:
    def beautifulSplits(self, nums: List[int]) -> int:
        n = len(nums)
        if n < 3:
            return 0

        # zg[i] is the LCP of nums and nums[i:].
        zg = [0] * n
        zg[0] = n
        left = right = 0
        for i in range(1, n):
            if i < right:
                zg[i] = min(right - i, zg[i - left])
            while i + zg[i] < n and nums[zg[i]] == nums[i + zg[i]]:
                zg[i] += 1
            if i + zg[i] > right:
                left, right = i, i + zg[i]

        ans = 0
        for start in range(1, n - 1):
            # Z-array for the suffix beginning at start.
            m = n - start
            z = [0] * m
            z[0] = m
            left = right = 0
            for off in range(1, m):
                if off < right:
                    z[off] = min(right - off, z[off - left])
                while off + z[off] < m and nums[start + z[off]] == nums[start + off + z[off]]:
                    z[off] += 1
                if off + z[off] > right:
                    left, right = off, off + z[off]

            # Condition 1: nums[:start] is a prefix of the second part.
            branch1 = zg[start] >= start
            hi1 = n - start - 1
            c1 = max(0, hi1 - start + 1) if branch1 else 0

            # Condition 2: the second part of length d prefixes the third.
            c2 = 0
            overlap = 0
            for d in range(1, (n - start) // 2 + 1):
                if z[d] >= d:
                    c2 += 1
                    if branch1 and d >= start:
                        overlap += 1

            ans += c1 + c2 - overlap
        return ans

