class Solution:
    def maxRemovals(self, source: str, pattern: str, targetIndices: List[int]) -> int:
        m = len(pattern)
        neg = -10**9
        dp = [neg] * (m + 1)
        dp[0] = 0
        targets = set(targetIndices)
        for i, ch in enumerate(source):
            gain = int(i in targets)
            ndp = [v + gain if v != neg else neg for v in dp]
            for j in range(m):
                if dp[j] != neg and ch == pattern[j] and dp[j] > ndp[j + 1]:
                    ndp[j + 1] = dp[j]
            dp = ndp
        return dp[m]

