class Solution:
    def minCost(self, n: int, cost: List[List[int]]) -> int:
        inf = 10**30
        # dp[a][b]: minimum cost for paired houses (i, n-1-i),
        # with colors a,b respectively; pair colors must differ.
        dp = [[inf] * 3 for _ in range(3)]
        half = n // 2
        for a in range(3):
            for b in range(3):
                if a != b:
                    dp[a][b] = cost[0][a] + cost[n - 1][b]

        for i in range(1, half):
            ndp = [[inf] * 3 for _ in range(3)]
            for a in range(3):
                for b in range(3):
                    if a == b:
                        continue
                    best = inf
                    for c in range(3):
                        for d in range(3):
                            if c != d and c != a and d != b:
                                best = min(best, dp[c][d])
                    ndp[a][b] = best + cost[i][a] + cost[n - 1 - i][b]
            dp = ndp

        return min(map(min, dp))

